#include "KS/SRC/ks/FEPanel_shared.h"

typedef unsigned int u_int;
#define NULL 0
#define NEW new
#define assert(x) ((void)0)

extern void KSReadFile(const char *, nglFileBuf *, unsigned int);
extern void KSReleaseFile(nglFileBuf *);

class PreformatText : public TextString
{
private:
    stringx* file_head;
    int start_line;
    int num_vis_lines;
    int max_lines;
    int actual_lines;
    static const int absolute_limit = 400;

public:
    void readText(char* filename, int max_lines, int vis_lines);
};

__asm__(".equ KSReadFile__FPCcP10nglFileBufUi, 0x001E32A0");
__asm__(".equ KSReleaseFile__FP10nglFileBuf, 0x001E3300");
__asm__(".equ MakeReplacements__10TextStringR7stringx, 0x001485A8");

void PreformatText::readText(char* filename, int ml, int vis_lines)
{
    max_lines = ml;
    num_vis_lines = vis_lines;
    start_line = 0;
    file_head = NEW stringx[max_lines];
    assert(max_lines <= absolute_limit);
    const int line_size = 300;
    char line[line_size];
    u_int cur_index = 0;
    int line_index = 0, file_index = 0;

    nglFileBuf file;
    file.Buf=NULL; file.Size=0;
    KSReadFile(filename, &file, 1);
    unsigned char* buffer = (unsigned char*) file.Buf;
    if(!buffer)
    {
        KSReleaseFile(&file);
        assert(0);
    }

    buffer[file.Size] = '\0';

    while(cur_index < file.Size && buffer[cur_index] != '\x04')
    {
        line_index = 0;
        while(buffer[cur_index] != '\n' && buffer[cur_index] != '\r' && buffer[cur_index] != '\x04')
            if(line_index < line_size)
                line[line_index++] = buffer[cur_index++];
            else { line_index++; cur_index++; }

        if(buffer[cur_index] == '\r' && buffer[cur_index+1] == '\n')
            cur_index++;
        cur_index++;

        if(line_index >= line_size)
        {
            line[line_size-1] = '\0';
        }
        else
            line[line_index] = '\0';
        if(file_index >= max_lines)
            file_index++;
        else file_head[file_index++] = stringx(line);
    }

    if(file_index >= max_lines)
    {
    }

    KSReleaseFile(&file);

    actual_lines = file_index;

    for(int i=0; i<actual_lines; i++)
        MakeReplacements(file_head[i]);
}
